  ('d944ed66-6c68-5b01-93e0-a7ef39e9892f'::uuid, '00000000-0000-4000-8000-000000000201'::uuid, 'v1/00000000-0000-4000-8000-000000000201/02-gallery-49bcc8b73f45-960x1280.jpg', current_setting('app.kwabor_demo_media_base_url') || 'v1/00000000-0000-4000-8000-000000000201/02-gallery-49bcc8b73f45-960x1280.jpg', 'Passerelle fictive en bois traversant des herbes côtières au soleil couchant de Cotonou', 2, false, 'image'::public.listing_media_kind),
