  ('9a8cd814-5863-50ae-bf3d-938c5f53c8d8'::uuid, '00000000-0000-4000-8000-000000000202'::uuid, 'v1/00000000-0000-4000-8000-000000000202/01-gallery-75543b33f4f4-960x1280.jpg', current_setting('app.kwabor_demo_media_base_url') || 'v1/00000000-0000-4000-8000-000000000202/01-gallery-75543b33f4f4-960x1280.jpg', 'Arcade fictive en briques ocre décorée de poteries sobres dans la cour de Ganhi', 1, false, 'image'::public.listing_media_kind),
