) as desired (id, type, subtype, listing_class, category_id, status, name, slug, description, content_lang, city_id, district, address, lat, lng, price_from_xof, price_unit, price_tier, opening_hours, contact_phone, contact_whatsapp, external_url, email, socials, tags, verified, rating_avg, rating_count, views_count, likes_count, published_at)
