-- Content updates exclude interaction counters and fire only on a real difference.
update public.listings as target
set
  type = desired.type,
  subtype = desired.subtype,
  listing_class = desired.listing_class,
  category_id = desired.category_id,
  name = desired.name,
  slug = desired.slug,
  description = desired.description,
  content_lang = desired.content_lang,
  city_id = desired.city_id,
  district = desired.district,
  address = desired.address,
  lat = desired.lat,
  lng = desired.lng,
  price_from_xof = desired.price_from_xof,
  price_unit = desired.price_unit,
  price_tier = desired.price_tier,
  opening_hours = desired.opening_hours,
  contact_phone = desired.contact_phone,
  contact_whatsapp = desired.contact_whatsapp,
  external_url = desired.external_url,
  email = desired.email,
  socials = desired.socials,
  tags = desired.tags,
