from (values
  ('00000000-0000-4000-8000-000000000201'::uuid, 'lieu'::public.listing_type, 'nature', 'patrimonial'::public.listing_class, 'heritage-nature', 'Jardin des Brises du Littoral', 'jardin-brises-littoral-cotonou-demo', 'Jardin côtier fictif composé de palmiers, graminées et bancs ombragés, conçu pour évoquer une pause fraîche près du littoral de Cotonou. Cette fiche et ses conditions de visite sont entièrement fictives et réservées à la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Fidjrossè', 'Adresse fictive, secteur littoral de Fidjrossè, Cotonou', 6.3538, 2.3532, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'nature', 'littoral', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000202'::uuid, 'lieu'::public.listing_type, 'historique', 'patrimonial'::public.listing_class, 'heritage-historique', 'Cour des Mémoires de Ganhi', 'cour-memoires-ganhi-cotonou-demo', 'Cour patrimoniale fictive où briques ocre, arcades sobres et objets du quotidien composent un parcours intimiste sur la mémoire urbaine. Le lieu, le récit et les modalités de visite sont inventés pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Ganhi', 'Adresse fictive, quartier Ganhi, Cotonou', 6.3609, 2.4302, 1500, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'histoire', 'architecture', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000203'::uuid, 'lieu'::public.listing_type, 'nature', 'patrimonial'::public.listing_class, 'heritage-nature', 'Mangrove Urbaine d''Agla', 'mangrove-urbaine-agla-cotonou-demo', 'Petit refuge écologique fictif parcouru par une passerelle légère entre palétuviers, eau saumâtre et observatoires ombragés. Le site et toutes les informations de visite sont inventés pour démontrer l''expérience Kwabor en bêta fermée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Agla', 'Adresse fictive, lisière humide d''Agla, Cotonou', 6.3831, 2.3455, 1000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'nature', 'mangrove', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000204'::uuid, 'lieu'::public.listing_type, 'marche', 'commercial'::public.listing_class, 'commercial-marche', 'Marché des Paniers du Lac', 'marche-paniers-lac-cotonou-demo', 'Marché fictif à taille humaine mettant en scène paniers, nattes et objets en fibres naturelles dans des kiosques inspirés du bord de lac. Cette fiche est un contenu de démonstration inventé pour la bêta fermée Kwabor, sans vendeur ni offre réelle. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Ladji', 'Adresse fictive, rive de Ladji, Cotonou', 6.3888, 2.4327, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'marche', 'vannerie', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000205'::uuid, 'lieu'::public.listing_type, 'nature', 'patrimonial'::public.listing_class, 'heritage-nature', 'Sentier des Palétuviers Rouges', 'sentier-paletuviers-rouges-ouidah-demo', 'Sentier écologique fictif serpentant entre palétuviers, lagune et petites plateformes d''observation, pensé pour une découverte lente du paysage côtier. Ce lieu et toutes ses informations sont inventés pour la démonstration de la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Avlékété', 'Adresse fictive, zone lagunaire d''Avlékété, Ouidah', 6.3387, 2.0568, 1200, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'nature', 'lagune', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000206'::uuid, 'lieu'::public.listing_type, 'historique', 'patrimonial'::public.listing_class, 'heritage-historique', 'Cour des Tambours de Zomaï', 'cour-tambours-zomai-ouidah-demo', 'Cour culturelle fictive organisée autour de tambours sculptés, de murs en terre et d''un patio ombragé destiné à des récits sonores imaginaires. Le site, sa collection et ses conditions d''accès sont inventés pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Zomaï', 'Adresse fictive, quartier Zomaï, Ouidah', 6.3672, 2.0886, 2000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'histoire', 'musique', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000207'::uuid, 'lieu'::public.listing_type, 'nature', 'patrimonial'::public.listing_class, 'heritage-nature', 'Jardin des Dunes de Djègbadji', 'jardin-dunes-djegbadji-ouidah-demo', 'Jardin de dunes fictif mêlant plantes côtières, cheminements de bois et petits belvédères ouverts sur un paysage de sable préservé. La destination et les informations présentées sont entièrement inventées pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Djègbadji', 'Adresse fictive, dunes de Djègbadji, Ouidah', 6.3355, 2.1024, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'nature', 'dunes', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000208'::uuid, 'lieu'::public.listing_type, 'marche', 'commercial'::public.listing_class, 'commercial-marche', 'Marché des Teinturières d''Avlékété', 'marche-teinturieres-avlekete-ouidah-demo', 'Marché-atelier fictif consacré aux étoffes teintes, aux bains de couleur et aux fibres suspendues dans une cour ventilée. La fiche, les artisans et les offres sont inventés exclusivement pour montrer le potentiel de la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Avlékété', 'Adresse fictive, village d''Avlékété, Ouidah', 6.3482, 2.0477, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'marche', 'textile', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000209'::uuid, 'lieu'::public.listing_type, 'historique', 'patrimonial'::public.listing_class, 'heritage-historique', 'Maison des Voûtes d''Adjina', 'maison-voutes-adjina-porto-novo-demo', 'Maison patrimoniale fictive aux voûtes généreuses, carreaux colorés et cour intérieure végétalisée, imaginée comme un lieu de lecture de la ville. Le bâtiment et son histoire sont des créations réservées à la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Adjina', 'Adresse fictive, quartier Adjina, Porto-Novo', 6.4985, 2.6254, 1800, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'histoire', 'voutes', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000210'::uuid, 'lieu'::public.listing_type, 'nature', 'patrimonial'::public.listing_class, 'heritage-nature', 'Escale Verte de la Lagune', 'escale-verte-lagune-porto-novo-demo', 'Escale naturelle fictive aménagée sur une rive paisible avec ponton, plantes aquatiques et abris légers tournés vers la lagune. Cette destination et ses informations sont inventées uniquement pour illustrer la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Akonaboè', 'Adresse fictive, rive d''Akonaboè, Porto-Novo', 6.4857, 2.6411, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'nature', 'lagune', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000211'::uuid, 'lieu'::public.listing_type, 'historique', 'patrimonial'::public.listing_class, 'heritage-historique', 'Passage des Masques de Tokpota', 'passage-masques-tokpota-porto-novo-demo', 'Passage patrimonial fictif reliant deux petites cours où des formes sculptées originales racontent une histoire imaginaire de métiers et de fêtes. Le lieu, les œuvres et le récit sont inventés pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Tokpota', 'Adresse fictive, quartier Tokpota, Porto-Novo', 6.5098, 2.6197, 1000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'histoire', 'sculpture', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000212'::uuid, 'lieu'::public.listing_type, 'marche', 'commercial'::public.listing_class, 'commercial-marche', 'Halle des Potières d''Akpassa', 'halle-potieres-akpassa-porto-novo-demo', 'Halle fictive consacrée à des poteries contemporaines, avec démonstrations imaginaires, étagères en terre et patio de cuisson mis en scène. La fiche, les créateurs et les objets sont inventés pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Akpassa', 'Adresse fictive, quartier Akpassa, Porto-Novo', 6.4863, 2.6168, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'marche', 'poterie', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000213'::uuid, 'lieu'::public.listing_type, 'marche', 'commercial'::public.listing_class, 'commercial-marche', 'Marché des Étoffes Indigo', 'marche-etoffes-indigo-porto-novo-demo', 'Marché fictif aux galeries étroites où étoffes indigo, fibres naturelles et accessoires sans marque composent une promenade très visuelle. Tous les exposants, produits et renseignements sont inventés pour la bêta fermée Kwabor. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Ouando', 'Adresse fictive, quartier Ouando, Porto-Novo', 6.5127, 2.6034, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'marche', 'indigo', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000214'::uuid, 'lieu'::public.listing_type, 'historique', 'patrimonial'::public.listing_class, 'heritage-historique', 'Porte du Non-Retour', 'porte-du-non-retour', 'Monument patrimonial réel de Ouidah présenté comme repère du parcours mémoriel. Le texte éditorial, les conditions de visite et les visuels de cette fiche sont des éléments de démonstration générés non documentaires. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Plage de Ouidah', 'Route des Esclaves, Ouidah', 6.3422, 2.08, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'histoire', 'patrimoine', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000215'::uuid, 'lieu'::public.listing_type, 'marche', 'commercial'::public.listing_class, 'commercial-marche', 'Marche Dantokpa', 'marche-dantokpa', 'Grand marché réel de Cotonou, présenté ici comme repère visuel du catalogue. Les données d''activité, la sélection d''étals et les visuels de cette fiche sont des démonstrations générées non documentaires. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Dantokpa', 'Boulevard Saint Michel, Cotonou', 6.3707, 2.431, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'marche', 'cotonou', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000301'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Escales Sonores du Littoral', 'escales-sonores-littoral-cotonou-demo', 'Soirée musicale fictive mêlant percussions douces, cordes et paysages sonores dans un jardin côtier imaginaire de Cotonou. L''événement, sa programmation, ses tarifs et ses organisateurs sont inventés uniquement pour la bêta fermée Kwabor; aucune réservation réelle n''est proposée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Fidjrossè', 'Adresse fictive, Jardin des Brises du Littoral, Cotonou', 6.3538, 2.3532, 3000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'musique', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000302'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Atelier Couleurs de Cotonou', 'atelier-couleurs-cotonou-demo', 'Atelier créatif fictif autour de pigments, papiers et compositions abstraites inspirées des teintes urbaines de Cotonou. Le rendez-vous, les intervenants et les places disponibles sont inventés pour la bêta fermée Kwabor; aucune inscription réelle n''est ouverte. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Zongo', 'Adresse fictive, Halle des Tisserands de Zongo, Cotonou', 6.3736, 2.4251, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'atelier', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000303'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Scène des Contes Urbains', 'scene-contes-urbains-cotonou-demo', 'Veillée fictive de récits contemporains mise en scène dans une cour imaginaire de Ganhi, avec objets sonores et décors minimalistes. La programmation, l''équipe et la billetterie sont inventées pour la bêta fermée Kwabor; aucun billet réel n''est vendu. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Ganhi', 'Adresse fictive, Cour des Mémoires de Ganhi, Cotonou', 6.3609, 2.4302, 2000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'contes', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000304'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Balade Photo des Lumières du Port', 'balade-photo-lumieres-port-cotonou-demo', 'Parcours photo fictif consacré aux reflets, textures et lumières de la ville, scénarisé autour d''un refuge écologique imaginaire. Le rendez-vous, l''encadrement et les places sont inventés pour la bêta fermée Kwabor; aucune inscription réelle n''existe. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Agla', 'Adresse fictive, Mangrove Urbaine d''Agla, Cotonou', 6.3831, 2.3455, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'photo', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000305'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Rencontres Danse des Quartiers', 'rencontres-danse-quartiers-cotonou-demo', 'Rencontres chorégraphiques fictives imaginées comme une succession de formes courtes dans un marché au bord de l''eau. Les artistes, le programme, les tarifs et l''organisation sont inventés pour la bêta fermée Kwabor; aucune vente réelle n''est proposée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'cotonou', 'Ladji', 'Adresse fictive, Marché des Paniers du Lac, Cotonou', 6.3888, 2.4327, 2500, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'danse', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000306'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Cinéma des Dunes', 'cinema-dunes-ouidah-demo', 'Projection en plein air fictive dans un jardin de dunes imaginaire, avec écran sobre, assises légères et sélection de courts métrages inventés. La séance et ses participants sont créés pour la bêta fermée Kwabor; aucune inscription ni œuvre réelle n''est associée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Djègbadji', 'Adresse fictive, Jardin des Dunes de Djègbadji, Ouidah', 6.3355, 2.1024, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'cinema', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000307'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Laboratoire des Rythmes de la Côte', 'laboratoire-rythmes-cote-ouidah-demo', 'Session musicale fictive autour de rythmes originaux, d''instruments génériques et d''expérimentations acoustiques dans une cour imaginaire. Les artistes, l''atelier et les tarifs sont inventés pour la bêta fermée Kwabor; aucune billetterie réelle n''est ouverte. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Zomaï', 'Adresse fictive, Cour des Tambours de Zomaï, Ouidah', 6.3672, 2.0886, 3500, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'rythmes', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000308'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Parade des Lanternes d''Argile', 'parade-lanternes-argile-ouidah-demo', 'Installation-parade fictive de lanternes en argile et de formes lumineuses originales dans les allées d''un marché imaginaire. L''événement, les objets, les participants et le parcours sont inventés pour la bêta fermée Kwabor; aucune inscription réelle n''est proposée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Avlékété', 'Adresse fictive, Marché des Teinturières d''Avlékété, Ouidah', 6.3482, 2.0477, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'lanternes', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000309'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Journée des Saveurs du Littoral', 'journee-saveurs-littoral-ouidah-demo', 'Journée culinaire fictive mettant en scène recettes imaginaires, produits locaux génériques et tables de dégustation près d''une lagune inventée. Les cuisiniers, menus, tarifs et billets sont créés pour la bêta fermée Kwabor; aucun repas réel n''est vendu. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'ouidah', 'Avlékété', 'Adresse fictive, Sentier des Palétuviers Rouges, Ouidah', 6.3387, 2.0568, 3000, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'cuisine', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000310'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Matinée des Masques en Papier', 'matinee-masques-papier-porto-novo-demo', 'Atelier-exposition fictif de sculptures en papier aux formes entièrement originales, conçu pour explorer volumes, couleurs et ombres sans référence rituelle. Le programme, les œuvres et les participants sont inventés pour la bêta fermée Kwabor; aucune inscription réelle n''est ouverte. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Tokpota', 'Adresse fictive, Passage des Masques de Tokpota, Porto-Novo', 6.5098, 2.6197, null, 'aucune'::public.price_unit, null, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'papier', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
  ('00000000-0000-4000-8000-000000000311'::uuid, 'evenement'::public.listing_type, 'culture', 'evenementiel'::public.listing_class, 'event-culture', 'Salon du Livre des Lagunes', 'salon-livre-lagunes-porto-novo-demo', 'Salon littéraire fictif installé face à la lagune, avec ouvrages imaginaires, coins de lecture et conversations scénarisées. Les auteurs, titres, tarifs et organisateurs sont inventés pour la bêta fermée Kwabor; aucune publication ni billetterie réelle n''est associée. Contenu fictif créé pour la bêta fermée Kwabor.', 'fr', 'porto-novo', 'Akonaboè', 'Adresse fictive, Escale Verte de la Lagune, Porto-Novo', 6.4857, 2.6411, 1500, 'par_entree'::public.price_unit, 1, '{}'::jsonb, null, null, null, null, '{}'::jsonb, array['demo-kwabor', 'contenu-fictif', 'culture', 'livres', 'demo-catalog:2d0affd1fe5', 'demo-anchor:20260812']::text[], false),
