-- Diff sets remove only obsolete generated children; unchanged rows remain untouched.
delete from public.listing_media existing
using kwabor_demo_expected_listings parent
where existing.listing_id = parent.id
  and parent.detail_variant in ('food', 'lodging', 'place')
  and not exists (
    select 1 from kwabor_demo_expected_media expected where expected.id = existing.id
  );

delete from public.listing_amenities existing
using kwabor_demo_expected_listings parent
where existing.listing_id = parent.id
  and parent.detail_variant in ('food', 'lodging', 'place')
  and not exists (
    select 1
    from kwabor_demo_expected_amenities expected
    where expected.listing_id = existing.listing_id
      and expected.amenity_id = existing.amenity_id
  );

delete from public.room_types existing
using kwabor_demo_expected_listings parent
where existing.listing_id = parent.id
  and parent.detail_variant = 'lodging'
  and not exists (
    select 1 from kwabor_demo_expected_rooms expected where expected.id = existing.id
  );

on conflict (listing_id) do update set
  place_category = excluded.place_category,
  is_free = excluded.is_free,
  entry_fee_xof = excluded.entry_fee_xof,
  fee_note = excluded.fee_note
where row(target.place_category, target.is_free, target.entry_fee_xof, target.fee_note) is distinct from row(excluded.place_category, excluded.is_free, excluded.entry_fee_xof, excluded.fee_note);

on conflict (listing_id) do update set
  star_rating = excluded.star_rating,
  room_count = excluded.room_count,
  checkin_time = excluded.checkin_time,
  checkout_time = excluded.checkout_time
where row(target.star_rating, target.room_count, target.checkin_time, target.checkout_time) is distinct from row(excluded.star_rating, excluded.room_count, excluded.checkin_time, excluded.checkout_time);

on conflict (id) do update set
  listing_id = excluded.listing_id,
  name = excluded.name,
  price_xof = excluded.price_xof,
  display_order = excluded.display_order
where row(target.listing_id, target.name, target.price_xof, target.display_order) is distinct from row(excluded.listing_id, excluded.name, excluded.price_xof, excluded.display_order);

on conflict (listing_id) do update set
  cuisines = excluded.cuisines,
  meals = excluded.meals,
  reservation = excluded.reservation,
  menu_url = excluded.menu_url
where row(target.cuisines, target.meals, target.reservation, target.menu_url) is distinct from row(excluded.cuisines, excluded.meals, excluded.reservation, excluded.menu_url);

on conflict (listing_id, amenity_id) do update set
  display_order = excluded.display_order
where row(target.display_order) is distinct from row(excluded.display_order);

on conflict (id) do update set
  listing_id = excluded.listing_id,
  storage_path = excluded.storage_path,
  url = excluded.url,
  alt = excluded.alt,
  display_order = excluded.display_order,
  is_cover = excluded.is_cover,
  kind = excluded.kind
where row(target.listing_id, target.storage_path, target.url, target.alt, target.display_order, target.is_cover, target.kind) is distinct from row(excluded.listing_id, excluded.storage_path, excluded.url, excluded.alt, excluded.display_order, excluded.is_cover, excluded.kind);

